function objCorners(o:Obj|Opening){return rectCorners(o.x,o.y,o.width,'depth' in o?o.depth:.16,o.rotation)}
function wallCorners(w:Wall){const l=dist(w.start,w.end),a=ang(w.start,w.end),c={x:(w.start.x+w.end.x)/2,y:(w.start.y+w.end.y)/2},hl=l/2,hd=w.thickness/2;return[rot({x:c.x-hl,y:c.y-hd},c,a),rot({x:c.x+hl,y:c.y-hd},c,a),rot({x:c.x+hl,y:c.y+hd},c,a),rot({x:c.x-hl,y:c.y+hd},c,a)]}
function pts(p:Point[]){return p.map(q=>`${q.x*SCALE},${q.y*SCALE}`).join(' ')}
function elev(id:string){return LEVELS.find(l=>l.id===id)?.elevation??0}
function hex(h:string){return parseInt(h.replace('#',''),16)}
function areaM2(a:Area){return Math.abs(a.width*a.depth)}
function wallLen(w:Wall){return dist(w.start,w.end)}
