 function addAreaAt(p:Point){if(areaStart){const x=(areaStart.x+p.x)/2,y=(areaStart.y+p.y)/2,w=Math.max(.2,Math.abs(p.x-areaStart.x)),d=Math.max(.2,Math.abs(p.y-areaStart.y));const a:Area={id:Date.now(),levelId:level,type:areaType,x,y,width:w,depth:d,rotation:0,material:areaType,thickness:.1};setAreas(v=>[...v,a]);setAreaStart(null);setSelection({type:'area',id:a.id});setMode('select');setStatus('Bodenfläche erstellt und auswählbar/verschiebbar.')}else{setAreaStart(p);setStatus('Ersten Eckpunkt gesetzt. Zweiten Eckpunkt setzen.')}}
