 function loadBrowser(){const r=localStorage.getItem(STORE);if(!r)return setStatus('Kein Browser-Projekt gefunden.');const p=JSON.parse(r);setAreas(p.areas??[]);setObjects(p.objects??[]);setWalls(p.walls??[]);setOpenings(p.openings??[]);setBg(p.bg??null);if(p.cam)setCam(p.cam)}
