 function exportCsv(){const rows=[['Kategorie','Ebene','Typ','Material','Länge/Breite','Tiefe/Dicke','Höhe','m²','m³'],...areas.map(a=>['Fläche',a.levelId,a.type,a.material,a.width.toFixed(2),a.depth.toFixed(2),a.thickness.toFixed(2),areaM2(a).toFixed(2),(areaM2(a)*a.thickness).toFixed(2)]),...objects.map(o=>['Objekt',o.levelId,o.type,o.material,o.width.toFixed(2),o.depth.toFixed(2),o.height.toFixed(2),'',(o.width*o.depth*o.height).toFixed(2)]),...walls.map(w=>['Wand',w.levelId,w.name,w.material,wallLen(w).toFixed(2),w.thickness.toFixed(2),w.height.toFixed(2),(wallLen(w)*w.height).toFixed(2),(wallLen(w)*w.thickness*w.height).toFixed(2)]),...openings.map(o=>['Bauteil',o.levelId,o.type,o.material,o.width.toFixed(2),'',o.height.toFixed(2),(o.width*o.height).toFixed(2),''])];download('al-green-design-v010.csv',rows.map(r=>r.map(c=>`"${String(c).replaceAll('"','""')}"`).join(';')).join('\n'),'text/csv;charset=utf-8')}
 function exportDxf(){const lines=['0','SECTION','2','HEADER','9','$ACADVER','1','AC1009','0','ENDSEC','0','SECTION','2','ENTITIES'];const add=(a:Point,b:Point,lay:string)=>lines.push('0','LINE','8',lay,'10',String(a.x),'20',String(-a.y),'30','0','11',String(b.x),'21',String(-b.y),'31','0');const poly=(p:Point[],lay:string)=>p.forEach((q,i)=>add(q,p[(i+1)%p.length],lay));areas.forEach(a=>poly(areaCorners(a),`AREA_${a.type}`));objects.forEach(o=>poly(objCorners(o),`OBJECT_${o.type}`));walls.forEach(w=>{poly(wallCorners(w),'WALLS');add(w.start,w.end,'WALL_AXIS')});openings.forEach(o=>poly(objCorners(o),`OPENING_${o.type}`));lines.push('0','ENDSEC','0','EOF');download('al-green-design-v010.dxf',lines.join('\n'),'application/dxf')}
 function serializeSvg(){return svgRef.current?new XMLSerializer().serializeToString(svgRef.current):''}
 async function exportRaster(type:'png'|'jpeg'|'webp'){if(view==='3d'){const c=threeHostRef.current?.querySelector('canvas');if(!c)return;const mime=type==='png'?'image/png':type==='jpeg'?'image/jpeg':'image/webp';const a=document.createElement('a');a.href=c.toDataURL(mime,.92);a.download=`garden-studio-3d-v010.${type==='jpeg'?'jpg':type}`;a.click();return}const blob=new Blob([serializeSvg()],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=1800;c.height=1200;const ctx=c.getContext('2d');if(!ctx)return;ctx.fillStyle='#eef2f7';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);const mime=type==='png'?'image/png':type==='jpeg'?'image/jpeg':'image/webp',a=document.createElement('a');a.href=c.toDataURL(mime,.92);a.download=`garden-studio-v010.${type==='jpeg'?'jpg':type}`;a.click();URL.revokeObjectURL(url)};img.src=url}
 async function exportPdf(){const {jsPDF}=await import('jspdf');let data='',w=1800,h=1200;if(view==='3d'){const c=threeHostRef.current?.querySelector('canvas');if(!c)return;data=c.toDataURL('image/png');w=c.width;h=c.height}else{const blob=new Blob([serializeSvg()],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),img=new Image();await new Promise<void>(res=>{img.onload=()=>res();img.src=url});const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');if(!ctx)return;ctx.fillStyle='#eef2f7';ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);data=c.toDataURL('image/png');URL.revokeObjectURL(url)}const pdf=new jsPDF({orientation:'landscape',unit:'px',format:[w,h]});pdf.addImage(data,'PNG',0,0,w,h);pdf.save(view==='3d'?'garden-studio-3d-v010.pdf':'garden-studio-v010.pdf')}
